{
 "research_concepts": [
  "Player roles and archetypes (e.g., shapers, cut-heavy, drive-heavy)",
  "Offensive play-types (cuts, drives)",
  "Player performance transferability / portability across contexts (e.g., teams, seasons)"
 ],
 "methodological_questions": [
  "How to classify players based on offensive play-type usage (e.g., cut-heavy vs. drive-heavy).",
  "How to measure the \"travel\" or transferability of a player's role or impact.",
  "What metrics are suitable for evaluating offensive role effectiveness.",
  "How to identify \"shapers\" or primary initiators of offense.",
  "How to account for small sample sizes in player movement analysis."
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF-CHT-057",
   "status_as_recorded": "supported",
   "finding": "Pre-move cut share (vs drive share) predicts whether a connector's organizational function reproduces after a move. Cut share rho=+0.265 p=0.011 AUC 0.653. Cut-drive rho=+0.314 p=0.002 AUC 0.656. Drive rho=-0.278 p=0.007. Top cut tercile 65% portable median Delta +0.167; bottom 35% median -0.039. LOO AUC 0.622; permutation p=0.005."
  },
  {
   "id": "FAM:SF-APPM-014",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Audit overall FAIL: OTHER 20.2% vs <10% target; 40.8% low confidence; DRIVE foul-draw 1.7% vs 14-22% benchmark; most PTs PPP above benchmark band; MIA identity checks fail."
  },
  {
   "id": "FAM:SF-CHT-025",
   "status_as_recorded": "artifact",
   "finding": "OTHER: 36% end in fouls, PPP inflated (FOUL_BUCKET). DRIVE: 12pp below foul benchmark (FOUL_LEAK). PNR shows 22% foul rate. Only 335 of 50,668 possessions (0.7%) map to a real play type via initiation_type."
  },
  {
   "id": "FAM:SF-CHT-029",
   "status_as_recorded": "artifact",
   "finding": "Play-type actions have decaying cross-possession memory (lag-1 effect >= lag-2; not just score margin or team quality). FAILED decay-sanity: DRIVE lifts +0.015,+0.020,+0.018,+0.021,+0.020 (flat). Within-team: DRIVE lag-1 +0.015 to -0.002. Cohen d ~0.01-0.03; p~0 from n>150k. Callable play-type horizons = 0. Flat non-decaying lifts collapse under within-team baseline; team-quality confound."
  },
  {
   "id": "FAM:SF-APPS-011",
   "status_as_recorded": "supported",
   "finding": "DRIVE PPP is materially higher in RS than playoffs, so an RS-calibrated optimizer over-recommends DRIVE. DRIVE RS 1.198 vs PO 0.912 (-0.286, 25 teams); PNR -0.173; PULL_UP +0.301; others within -0.07."
  },
  {
   "id": "FAM:SF-APPS-088",
   "status_as_recorded": "supported",
   "finding": "Connector absence displaces team offensive identity (D_A) more than usage-matched non-organizer absence. Unmatched conn vs role D_A 0.2020 vs 0.1021, t=5.97 p=2.87e-08. Usage-matched vs role: paired dD_A +0.1151, P(conn>ctrl)=81.2%, t=6.35 p=7.35e-09 n=96. Vs terminal: +0.0777 t=2.37 p=0.0261 n=25."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-APPM-014",
   "what_failed": "Inferred play-type labels match benchmark volumes, foul rates, PPP and known team identities.",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw), LIM:label_or_classification_error, LIM:leakage, LIM:small_sample, RISK:LABEL_ERROR, RISK:LEAKAGE_LOOKAHEAD, RISK:SAMPLE_SIZE_POWER"
  },
  {
   "id": "FAM:SF-CHT-025",
   "what_failed": "Play-type PPP differences are real efficiency, not labeling/foul artifacts.",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)"
  },
  {
   "id": "FAM:SF-CHT-029",
   "what_failed": "Play-type actions have decaying cross-possession memory (lag-1 effect >= lag-2; not just score margin or team quality).",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw), LIM:confounding, RISK:CONFOUNDING"
  }
 ],
 "evidence_establishes": [
  "The portability of player roles based on cut vs. drive share has been studied for 'connectors,' with cut share positively predicting portability and drive share negatively predicting it (FAM:SF-CHT-057).",
  "There are significant, well-documented issues with the accuracy and reliability of inferred play-type labels, especially for 'DRIVE' and 'OTHER,' including misattribution of fouls and low confidence (FAM:SF-APPM-014, FAM:SF-CHT-025).",
  "The effectiveness (PPP) of 'DRIVE' play types differs significantly between regular season and playoffs, suggesting context-dependency (FAM:SF-APPS-011).",
  "Confounding by team quality is a significant risk when evaluating play-type effects and player impact (FAM:SF-CHT-029).",
  "The concept of 'offensive identity' and its resilience to player absence has been established, distinguishing 'connectors' from other roles (FAM:SF-APPS-088)."
 ],
 "evidence_does_not_establish": [
  "Whether the findings on 'connector' portability (FAM:SF-CHT-057) extend to 'shapers' (primary initiators/high-usage players), as these roles may have different dynamics.",
  "A robust, validated method for classifying players as 'cut-heavy' or 'drive-heavy' shapers given the known issues with play-type labels.",
  "A reliable measure of 'travel' or transferability specifically for 'shapers' that accounts for the identified label issues and contextual differences (e.g., RS vs. Playoffs).",
  "How to adequately control for team quality and other confounders when assessing role transferability for shapers.",
  "Whether the existing play-type labeling issues have been resolved or mitigated in the current data pipeline."
 ],
 "own_inferences": [
  "The severe issues with play-type labels, particularly for 'DRIVE' and foul attribution, make it extremely challenging to reliably classify players as 'cut-heavy' or 'drive-heavy' and measure their impact or role effectiveness.",
  "The distinction between 'connectors' (studied in FAM:SF-CHT-057) and 'shapers' (the current research question) is important; shapers likely have higher usage and different responsibilities, meaning connector findings may not directly translate.",
  "The available data on play-by-play and derived play-type records, while the source of the problematic labels, is the only means to attempt this classification. A robust re-auditing and potential re-engineering of the play-type labels would be a prerequisite."
 ],
 "uncertainties": [
  "The current status of the play-type labeling system: whether the issues identified in FAM:SF-APPM-014 and FAM:SF-CHT-025 have been addressed or if the data available still suffers from these flaws.",
  "The precise definition and operationalization of 'shapers' and 'travel better' in a quantifiable manner.",
  "The number of actual 'shaper' movers available in the n=24 units of data, which could lead to very small sample sizes similar to previous studies (e.g., n=92 for connectors in FAM:SF-CHT-057)."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "The historical evidence, particularly FAM:SF-APPM-014 and FAM:SF-CHT-025, reveals critical and pervasive issues with the underlying play-type labels ('DRIVE', 'OTHER', foul attribution) that are fundamental to defining 'cut-heavy' and 'drive-heavy' players. These issues directly undermine the reliability of any classification or measurement based on these play types. While FAM:SF-CHT-057 provides some support for the general concept of cut/drive portability for 'connectors,' the severe data quality concerns for the core definitions necessitate a decision not to proceed as originally stated. The decision changed from potentially proceeding to not proceeding without significant prior data remediation."
 },
 "testability": {
  "p_testable": 0.1,
  "blocking_constraints": [
   {
    "code": "LABEL_ERROR",
    "text": "The foundational play-type labels (especially DRIVE and OTHER) are known to be inaccurate, unreliable, and suffer from foul leakage, making player classification into 'cut-heavy' or 'drive-heavy shapers' highly problematic and potentially artifact-prone. The 'initiation_type' mapping only 0.7% of possessions is a critical flaw."
   },
   {
    "code": "SAMPLE_SIZE_POWER",
    "text": "Even if labeling issues were resolved, the number of 'shaper' players who move teams and maintain a consistent role to be observed for 'travel' is likely very small, leading to underpowered analysis, as seen in related studies (e.g., n=92 for connectors)."
   },
   {
    "code": "CONFOUNDING",
    "text": "Team quality and surrounding talent are strong confounders when assessing player impact and role transferability, and prior attempts to account for this have led to artifactual results (FAM:SF-CHT-029)."
   }
  ]
 },
 "prior_work": {
  "already_answered": "partly",
  "cited": [
   "FAM:SF-CHT-057",
   "FAM:SF-APPS-088"
  ],
  "summary": "The portability of cut-heavy vs. drive-heavy roles has been studied for 'connectors' (FAM:SF-CHT-057), showing that cut share positively correlates with role reproduction after a move. The concept of offensive identity and its resilience to player absence (FAM:SF-APPS-088) is also established. However, these studies focused on 'connectors' or general offensive identity, not specifically 'shapers,' and did not fully resolve the underlying data quality issues with play-type labels that are critical for this question."
 },
 "risks": [
  {
   "code": "LABEL_ERROR",
   "text": "The primary risk is the unreliability of play-type labels, specifically 'DRIVE' and 'OTHER,' which are crucial for defining 'cut-heavy' and 'drive-heavy' shapers. Prior audits (FAM:SF-APPM-014, FAM:SF-CHT-025) show significant inaccuracies, foul leakage, and low confidence in these labels, making any classification or measurement based on them highly suspect."
  },
  {
   "code": "SAMPLE_SIZE_POWER",
   "text": "The number of players who qualify as 'shapers' and also move teams in the given data (n=24 units, likely 4 seasons) will be very limited, severely restricting statistical power for any comparative analysis of transferability."
  },
  {
   "code": "CONFOUNDING",
   "text": "Player performance and role effectiveness are heavily influenced by team context, coaching schemes, and surrounding talent. Isolating the effect of a player's inherent 'cut-heavy' or 'drive-heavy' style on transferability, independent of these strong confounders, will be extremely difficult (FAM:SF-CHT-029)."
  },
  {
   "code": "OUTCOME_DERIVED_LABEL",
   "text": "The 'travel' or portability of a role would need to be defined and measured. If this measure implicitly incorporates factors that are themselves related to the player's style (e.g., points per possession, which is known to vary by play type and context, FAM:SF-APPS-011), it could lead to circular reasoning or biased outcomes."
  },
  {
   "code": "DRIFT_NONSTATIONARITY",
   "text": "The effectiveness of play types can change across seasons and between regular season and playoffs (FAM:SF-APPS-011). A player's role might 'travel' differently depending on the specific seasons or contexts being compared, which could introduce non-stationarity."
  }
 ],
 "predicted_outcome": {
  "supported": 0.05,
  "rejected": 0.1,
  "untestable": 0.4,
  "artifact": 0.4,
  "uncertain": 0.05
 },
 "decision": "do_not_proceed",
 "design": {
  "estimand": "The difference in the probability of successful role transfer (or a quantitative measure of role reproduction) for 'cut-heavy shapers' versus 'drive-heavy shapers' after a team change.",
  "unit": "Player-season pairs (pre-move and post-move) for players identified as 'shapers' who change teams between seasons.",
  "sample": "All players identified as 'shapers' (e.g., top X% in usage, or primary initiator status) who change teams between any of the 2022-23, 2023-24, 2024-25, or 2025-26 seasons. Requires a minimum threshold of possessions for play-type classification in both pre- and post-move seasons.",
  "power": "Given the severe labeling issues and likely small sample of 'shaper' movers, achieving useful statistical power is highly improbable. A minimum viable test would aim for at least N=50 shaper movers per category (cut-heavy, drive-heavy) to detect a medium effect size (Cohen's d = 0.5) with 80% power, which is unlikely to be met.",
  "controls": "Control for player age, draft position, prior career performance (e.g., VORP, PER), new team quality, old team quality, change in role/usage, and surrounding talent in the new team. A regression-based approach or propensity score matching would be considered, if sufficient sample size allowed.",
  "falsification": "Null hypothesis: There is no difference in role transferability between cut-heavy and drive-heavy shapers. Falsification would occur if the observed difference is statistically significant and the effect size is meaningful after accounting for confounders. However, given the identified risks, a more immediate falsification would be the inability to reliably classify players or measure role reproduction due to data quality issues.",
  "multiplicity": "No explicit multiplicity correction planned for the core hypothesis, as it is a single primary question. However, if multiple measures of 'role reproduction' are explored, then p-value adjustment (e.g., Bonferroni or Holm-Bonferroni) would be applied.",
  "decision_rule": "Reject the null hypothesis if the p-value for the difference in portability between cut-heavy and drive-heavy shapers is less than 0.05, and the effect size is deemed practically significant. However, the primary decision rule before even reaching this point must be that the underlying play-type labels are validated and deemed reliable for this classification.",
  "data_version": "NBA 2022-23 to 2025-26 seasons, using the latest available play-by-play data and derived play-type possession records. Crucially, the play-type inferrer must be audited and, if necessary, re-engineered and validated before proceeding."
 }
}

